value.value:
frame "cache hit" {
  client -> api "GET"
  par {
    api -> cache "HIT"
    api -> logger "trace"
  }
  client <- api "value"
}

frame setup {
  +node client "Client"
  +node api    "API"
  +node db     "Database"
  +node cache  "Cache"
  +edge client api
  +edge api db
  +edge api cache
}

frame "write request" {
  client -> api "POST /user"
  api -> db "INSERT"
}

frame "invalidate cache" {
  api -> cache "DEL user:42"
}

frame respond {
  client <- api "201"
}
